import {initializeApp} from 'https://www.gstatic.com/firebasejs/11.0.2/firebase-app.js';
import {getAuth,onAuthStateChanged,signInWithEmailAndPassword,signOut} from 'https://www.gstatic.com/firebasejs/11.0.2/firebase-auth.js';
import {getFirestore,doc,collection,onSnapshot,getDoc,setDoc,updateDoc} from 'https://www.gstatic.com/firebasejs/11.0.2/firebase-firestore.js';
import {getFunctions,httpsCallable} from 'https://www.gstatic.com/firebasejs/11.0.2/firebase-functions.js';
import {firebaseConfig} from './firebase-config.js';

const app=initializeApp(firebaseConfig),auth=getAuth(app),db=getFirestore(app),functions=getFunctions(app);
const $=id=>document.getElementById(id);
const managers=new Set(['nikkhaikal@gmail.com','nealia.najihah@gmail.com']);
const dashboardRows=['Keyin','Net','Recruitment:','NAHP','AHP','Total HP','T/O','SHI Group','SHI Personal','WS Player'];
const hpRows=['Keyin','Net','Recruitment:','NAHP','AHP','Total HP','T/O','SHI Personal','WS Player'];
const months=['December','January','February','March','April','May'];
const totals=[['Recruitment','Recruitment:'],['NAHP','NAHP'],['AHP','AHP'],['Total HP','Total HP'],['Key in','Keyin'],['Net','Net']];
let dashboard={},hps=new Map(),selectedCode='',user=null,canManage=false,canEditDashboard=false,canEditHp=false,stopDashboard,stopHps,saveTimer;
function message(id,value='',kind=''){const el=$(id);el.textContent=value;el.className=`message ${kind}`}
function number(value){const n=Number(String(value??'').replaceAll(',','').trim());return Number.isFinite(n)?n:0}
function makeCell(text,key,editable,save){const td=document.createElement('td');td.textContent=text;td.contentEditable=editable?'true':'false';if(editable)td.addEventListener('blur',()=>save(key,td.textContent.trim()));return td}
function table(target,labels,values,prefix,editable,save){const body=$(target);body.replaceChildren();labels.forEach((name,i)=>{const tr=document.createElement('tr');for(const [field,fallback] of [['label',name],['target','—'],['actual','—']]){const key=`${prefix}-${i}-${field}`;tr.append(makeCell(values[key]??fallback,key,editable,save))}body.append(tr)})}
function saveDashboard(key,value){dashboard[key]=value;clearTimeout(saveTimer);saveTimer=setTimeout(()=>setDoc(doc(db,'dashboards','main'),dashboard).catch(e=>message('authMessage',e.message,'error')),350)}
async function saveHp(key,value){if(!selectedCode||!canEditHp)return;try{await updateDoc(doc(db,'hps',selectedCode),{[key]:value})}catch(e){message('hpMessage',e.message,'error')}}
function renderDashboard(){table('scoreTable',dashboardRows,dashboard,'score',canEditDashboard,saveDashboard);$('monthlyPlan').replaceChildren();months.forEach((month,i)=>{const box=document.createElement('div'),label=document.createElement('b'),content=document.createElement('span');box.className='month';label.textContent=month;content.textContent=dashboard[`month-${i}`]??'Add monthly focus';content.contentEditable=canEditDashboard?'true':'false';content.dataset.editable=String(canEditDashboard);if(canEditDashboard)content.addEventListener('blur',()=>saveDashboard(`month-${i}`,content.textContent.trim()));box.append(label,content);$('monthlyPlan').append(box)});$('editStatus').textContent=canEditDashboard?'Editing enabled':'View only'}
function renderScoreboard(){const board=$('scoreboard');board.replaceChildren();for(const [title,rowName] of totals){const i=hpRows.indexOf(rowName),sum=[...hps.values()].reduce((total,hp)=>total+number(hp[`hp-${i}-actual`]),0),card=document.createElement('div'),label=document.createElement('small'),value=document.createElement('strong');card.className='stat';label.textContent=`Total ${title}`;value.textContent=new Intl.NumberFormat('en-MY',{maximumFractionDigits:2}).format(sum);card.append(label,value);board.append(card)}}
function renderHpSelect(){const select=$('hpSelect'),previous=selectedCode;select.replaceChildren();if(!hps.size){const option=new Option('No HP accounts yet','');select.add(option);selectedCode=''}else{for(const [code,hp] of [...hps].sort((a,b)=>a[0].localeCompare(b[0])))select.add(new Option(`${code} · ${hp.name||'Unnamed HP'}`,code));selectedCode=hps.has(previous)?previous:select.options[0].value;select.value=selectedCode}renderHp()}
function renderHp(){const hp=hps.get(selectedCode);canEditHp=!!user&&(canManage||hp?.uid===user.uid||hp?.parentUid===user.uid);$('hpIdentity').textContent=hp?`${selectedCode} · ${hp.name||''}`:'Create the first HP account to start tracking.';table('hpTable',hpRows,hp||{},'hp',canEditHp,saveHp)}
function stopWatchers(){stopDashboard?.();stopHps?.();stopDashboard=stopHps=null}
function watch(){stopWatchers();stopDashboard=onSnapshot(doc(db,'dashboards','main'),snapshot=>{dashboard=snapshot.exists()?snapshot.data():{};renderDashboard()},e=>message('authMessage',e.message,'error'));stopHps=onSnapshot(collection(db,'hps'),snapshot=>{hps=new Map(snapshot.docs.map(d=>[d.id,d.data()]));renderHpSelect();renderScoreboard()},e=>message('hpMessage',e.message,'error'))}
$('hpSelect').addEventListener('change',e=>{selectedCode=e.target.value;renderHp()});
$('signIn').addEventListener('click',async()=>{try{message('authMessage');await signInWithEmailAndPassword(auth,$('email').value.trim(),$('password').value)}catch(e){message('authMessage','Sign in failed. Check your email and password.','error')}});
$('signOut').addEventListener('click',()=>signOut(auth));
$('createAccount').addEventListener('click',async()=>{const button=$('createAccount');button.disabled=true;try{const result=await httpsCallable(functions,'createAccount')({code:$('newCode').value.trim(),name:$('newName').value.trim(),email:$('newEmail').value.trim()});message('accountMessage',result.data.existingAccount?`HP ${result.data.code} linked to the existing account ${result.data.email}.`:`HP ${result.data.code} created for ${result.data.email}. Temporary password: ${result.data.temporaryPassword}`,'success');$('newCode').value=$('newName').value=$('newEmail').value=''}catch(e){message('accountMessage',e.message||'Could not create HP account.','error')}finally{button.disabled=false}});
onAuthStateChanged(auth,async current=>{stopWatchers();user=current;canManage=!!current&&managers.has((current.email||'').toLowerCase());let hasHp=false;if(current){try{const profile=await getDoc(doc(db,'users',current.uid));hasHp=!!profile.data()?.hpCode}catch(e){message('authMessage',e.message,'error')}}canEditDashboard=canManage;$('login').classList.toggle('hidden',!!current);$('session').classList.toggle('hidden',!current);$('accounts').classList.toggle('hidden',!(canManage||hasHp));$('userLabel').textContent=current?`${current.email} · ${canManage?'Team manager':'HP member'}`:'';if(current)watch();else{dashboard={};hps.clear();selectedCode='';renderDashboard();renderHpSelect();renderScoreboard();message('authMessage','Sign in to see Jiha’s team.')}});
$('today').textContent=new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'long',year:'numeric'}).format(new Date());renderDashboard();renderHpSelect();renderScoreboard();
